CREATE TABLE public.categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', display_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.categories TO anon, authenticated; GRANT ALL ON public.categories TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY categories_public ON public.categories FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id uuid NOT NULL REFERENCES public.categories(id) ON DELETE RESTRICT, name text NOT NULL, slug text NOT NULL UNIQUE, summary text NOT NULL DEFAULT '', detail text NOT NULL DEFAULT '', body_json jsonb NOT NULL DEFAULT '[]', specs_json jsonb NOT NULL DEFAULT '[]', sections_json jsonb NOT NULL DEFAULT '[]', thumbnail_url text NOT NULL DEFAULT '', subcategory text NOT NULL DEFAULT '', source_slug text NOT NULL DEFAULT '', missing text, display_order integer NOT NULL DEFAULT 0, is_published boolean NOT NULL DEFAULT true, catalogue_visible boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon, authenticated; GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY products_public ON public.products FOR SELECT TO anon, authenticated USING (is_published);
CREATE TABLE public.product_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, image_url text NOT NULL, filename text NOT NULL DEFAULT '', alt_text text NOT NULL DEFAULT '', display_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.product_images TO anon, authenticated; GRANT ALL ON public.product_images TO service_role;
ALTER TABLE public.product_images ENABLE ROW LEVEL SECURITY;
CREATE POLICY images_public ON public.product_images FOR SELECT TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.products WHERE products.id = product_images.product_id AND is_published));
CREATE TABLE public.admin_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.admin_users TO service_role;
ALTER TABLE public.admin_users ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.admin_login_limits (key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, window_start timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.admin_login_limits TO service_role;
ALTER TABLE public.admin_login_limits ENABLE ROW LEVEL SECURITY;
CREATE INDEX idx_products_category ON public.products(category_id);
CREATE INDEX idx_product_images_product ON public.product_images(product_id);
CREATE FUNCTION public.check_admin_login_limit(login_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE n integer; BEGIN INSERT INTO public.admin_login_limits(key, attempts) VALUES (login_key, 1) ON CONFLICT(key) DO UPDATE SET attempts = CASE WHEN admin_login_limits.window_start < now() - interval '15 minutes' THEN 1 ELSE admin_login_limits.attempts + 1 END, window_start = CASE WHEN admin_login_limits.window_start < now() - interval '15 minutes' THEN now() ELSE admin_login_limits.window_start END RETURNING attempts INTO n; RETURN n <= 10; END; $$;
REVOKE ALL ON FUNCTION public.check_admin_login_limit(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.check_admin_login_limit(text) TO service_role;
CREATE POLICY published_storage_read ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'product-images' AND EXISTS (SELECT 1 FROM public.product_images i JOIN public.products p ON p.id = i.product_id WHERE i.filename = storage.objects.name AND p.is_published));